    const output = await generate(input, true);
    try {
        return feedbackSchema.parse(JSON.parse(output));
    }
    catch {
        throw new ApiError(502, 'Gemini returned invalid feedback. Please try again.');
    }
}
export type ScenarioId = 'interview' | 'raise' | 'relationship' | 'feedback' | 'custom';
export type Difficulty = 'friendly' | 'neutral' | 'challenging';
export type ConversationMessage = {
    role: 'user' | 'assistant';
    content: string;
};
export type SessionInput = {
    scenarioId: ScenarioId;
    difficulty: Difficulty;
    customScenario?: string;
    messages: ConversationMessage[];
};
export type FeedbackReport = {
    summary: string;
    strengths: [
        string,
        string
    ];
    improvements: [
        string,
        string
    ];
    suggestedResponse: string;
};
import { speak } from '@/lib/server/gradium';
import { handle, readJson } from '@/lib/server/http';
import { speakSchema } from '@/lib/server/validation';
export const runtime = 'nodejs';
export async function POST(request: Request) {
    return handle(request, async () => {
        const { text } = await readJson(request, speakSchema);
        const bytes = await speak(text);
        return new Response(bytes as BodyInit, { headers: {
                'content-type': 'audio/wav', 'cache-control': 'no-store'
            } });
    });
}
import { converse } from '@/lib/server/gemini';
import { ApiError, handle, json, readJson } from '@/lib/server/http';
import { sessionSchema } from '@/lib/server/validation';
export const runtime = 'nodejs';
export async function POST(request: Request) {
    return handle(request, async () => {
        const input = await readJson(request, sessionSchema);
        if (input.messages.at(-1)?.role !== 'user')
            throw new ApiError(400, 'The last conversation message must be from the user.');
        return json(await converse(input));
    });
}
import { z } from 'zod';
export const sessionSchema = z.object({
    scenarioId: z.enum(['interview', 'raise', 'relationship', 'feedback', 'custom']), difficulty: z.enum(['friendly', 'neutral', 'challenging']), customScenario: z.string().trim().max(1500).optional(),
    messages: z.array(z.object({
        role: z.enum(['user', 'assistant']), content: z.string().trim().min(1).max(4000)
    }).strict()).min(1).max(40)
}).strict().refine(v => v.messages.some(m => m.role === 'user'), 'Provide at least one user answer.').refine(v => v.scenarioId !== 'custom' || Boolean(v.customScenario), 'Describe the custom scenario.').refine(v => v.messages.reduce((n, m) => n + m.content.length, 0) <= 24000, 'Conversation is too long.');
export const speakSchema = z.object({ text: z.string().trim().min(1).max(2000) }).strict();
export const feedbackSchema = z.object({
    summary: z.string().trim().min(1).max(2000), strengths: z.tuple([z.string().min(1).max(1000), z.string().min(1).max(1000)]), improvements: z.tuple([z.string().min(1).max(1000), z.string().min(1).max(1000)]), suggestedResponse: z.string().trim().min(1).max(4000)
}).strict();

