     1	'use client';
     2	
     3	import { useEffect, useRef, useState } from 'react';
     4	import { ArrowRight, Check, ChevronRight, MessageCircle, Mic, RotateCcw, Send, Sparkles, Square, Volume2 } from 'lucide-react';
     5	import { SCENARIOS } from '@/lib/scenarios';
     6	import type { ConversationMessage, FeedbackReport } from '@/lib/contracts';
     7	import { useVoiceSession } from '@/hooks/use-voice-session';
     8	import { Avatar, type AvatarState } from './avatar';
     9	
    10	type Difficulty = 'friendly' | 'neutral' | 'challenging';
    11	type Setup = { gemini: boolean; gradium: boolean };
    12	
    13	async function responseError(response: Response) {
    14	  const body = await response.json().catch(() => null);
    15	  return typeof body?.error === 'string' ? body.error : 'Something went wrong. Please try again.';
    16	}
    17	
    18	export function Coach() {
    19	  const [scenarioId, setScenarioId] = useState('interview');
    20	  const [difficulty, setDifficulty] = useState<Difficulty>('neutral');
    21	  const [customScenario, setCustomScenario] = useState('');
    22	  const [started, setStarted] = useState(false);
    23	  const [messages, setMessages] = useState<ConversationMessage[]>([]);
    24	  const [draft, setDraft] = useState('');
    25	  const [state, setState] = useState<AvatarState>('idle');
    26	  const [busy, setBusy] = useState(false);
    27	  const [micStarting, setMicStarting] = useState(false);
    28	  const [error, setError] = useState('');
    29	  const [report, setReport] = useState<FeedbackReport | null>(null);
    30	  const [setup, setSetup] = useState<Setup | null>(null);
    31	  const [setupFailed, setSetupFailed] = useState(false);
    32	  const recorder = useVoiceSession();
    33	  const lock = useRef(false);
    34	  const generation = useRef(0);
    35	  const controller = useRef<AbortController | null>(null);
    36	  const audio = useRef<HTMLAudioElement | null>(null);
    37	  const audioUrl = useRef<string | null>(null);
    38	  const transcriptEnd = useRef<HTMLDivElement | null>(null);
    39	  const scenario = SCENARIOS.find(item => item.id === scenarioId) ?? SCENARIOS[0];
    40	  const counterpart = ({ interview: 'Alex · Interviewer', raise: 'Alex · Your manager', relationship: 'Alex · Your partner', feedback: 'Alex · Your colleague', custom: 'Alex · Your counterpart' } as Record<string, string>)[scenarioId];
    41	  const hasUserTurn = messages.some(message => message.role === 'user');
    42	
    43	  function stopAudio() {
    44	    audio.current?.pause();
    45	    audio.current = null;
    46	    if (audioUrl.current) URL.revokeObjectURL(audioUrl.current);
    47	    audioUrl.current = null;
    48	  }
    49	
    50	  useEffect(() => {
    51	    const abort = new AbortController();
    52	    fetch('/api/status', { signal: abort.signal }).then(async response => {
    53	      if (!response.ok) throw new Error();
    54	      setSetup(await response.json());
    55	    }).catch(() => { if (!abort.signal.aborted) setSetupFailed(true); });
    56	    return () => { abort.abort(); controller.current?.abort(); stopAudio(); };
    57	  }, []);
    58	
    59	  useEffect(() => { transcriptEnd.current?.scrollIntoView({ block: 'nearest', behavior: 'instant' }); }, [messages, busy]);
    60	
    61	  function reset() {
    62	    generation.current += 1;
    63	    controller.current?.abort();
    64	    recorder.cancelRecording();
    65	    stopAudio();
    66	    lock.current = false;
    67	    setStarted(false); setMessages([]); setDraft(''); setReport(null);
    68	    setError(''); setState('idle'); setBusy(false); setMicStarting(false);
    69	  }
    70	
    71	  async function speak(text: string, token: number, signal: AbortSignal) {
    72	    if (!setup?.gradium) return;
    73	    try {
    74	      const response = await fetch('/api/speak', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text }), signal });
    75	      if (!response.ok) throw new Error(await responseError(response));
    76	      const blob = await response.blob();
    77	      if (token !== generation.current) return;
    78	      stopAudio();
    79	      audioUrl.current = URL.createObjectURL(blob);
    80	      const playback = new Audio(audioUrl.current);
    81	      audio.current = playback;
    82	      await new Promise<void>((resolve, reject) => {
    83	        playback.onended = () => resolve();
    84	        playback.onerror = () => reject(new Error('Audio could not play. Your reply is in the transcript.'));
    85	        signal.addEventListener('abort', () => { playback.pause(); resolve(); }, { once: true });
    86	        playback.play().then(() => { if (token === generation.current) setState('speaking'); }).catch(() => reject(new Error('Audio could not play. Your reply is in the transcript.')));
    87	      });
    88	    } catch (cause) {
    89	      if (token === generation.current && !signal.aborted) setError(cause instanceof Error ? `${cause.message} You can continue by typing.` : 'Speech unavailable. You can continue by typing.');
    90	    } finally { if (token === generation.current) stopAudio(); }
    91	  }
    92	
    93	  function begin() {
    94	    if (!setup?.gemini || (scenarioId === 'custom' && !customScenario.trim())) return;
    95	    setMessages([{ role: 'assistant', content: scenario.openingLine }]);
    96	    setStarted(true); setError('');
    97	  }
    98	
    99	  async function sendTurn(text: string, token: number, signal: AbortSignal) {
   100	    const next: ConversationMessage[] = [...messages, { role: 'user', content: text }];
   101	    setMessages(next); setDraft(''); setState('thinking');
   102	    const response = await fetch('/api/converse', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ scenarioId, difficulty, customScenario, messages: next }), signal });
   103	    if (!response.ok) throw new Error(await responseError(response));
   104	    const { reply } = await response.json();
   105	    if (token !== generation.current) return;
   106	    setMessages([...next, { role: 'assistant', content: reply }]);
   107	    await speak(reply, token, signal);
   108	  }
   109	
   110	  async function runTurn(source: 'text' | 'voice') {
   111	    if (lock.current || !setup?.gemini || (source === 'text' && !draft.trim())) return;
   112	    lock.current = true; setBusy(true); setError(''); stopAudio();
   113	    const token = generation.current;
   114	    const abort = new AbortController(); controller.current = abort;
   115	    try {
   116	      let text = draft.trim();
   117	      if (source === 'voice') {
   118	        setState('thinking');
   119	        const blob = await recorder.stopRecording();
   120	        const response = await fetch('/api/transcribe', { method: 'POST', headers: { 'Content-Type': 'audio/wav' }, body: blob, signal: abort.signal });
   121	        if (!response.ok) throw new Error(await responseError(response));
   122	        text = (await response.json()).text;
   123	      }
   124	      if (token === generation.current && text.trim()) await sendTurn(text, token, abort.signal);
   125	    } catch (cause) {
   126	      if (token === generation.current && !abort.signal.aborted) setError(cause instanceof Error ? cause.message : 'Could not send your answer. Please try again.');
   127	    } finally {
   128	      if (token === generation.current) { lock.current = false; setBusy(false); setState('idle'); }
   129	    }
   130	  }
   131	
   132	  async function toggleRecording() {
   133	    if (recorder.isRecording) { await runTurn('voice'); return; }
   134	    if (lock.current || busy) return;
   135	    const token = generation.current;
   136	    lock.current = true; setBusy(true); setMicStarting(true);
   137	    setError(''); stopAudio();
   138	    try { await recorder.startRecording(); } catch { /* Recorder displays its actionable error. */ }
   139	    finally {
   140	      if (token === generation.current) {
   141	        lock.current = false; setBusy(false); setMicStarting(false);
   142	      }
   143	    }
   144	  }
   145	
   146	  async function finish() {
   147	    if (lock.current || !hasUserTurn || recorder.isRecording) return;
   148	    lock.current = true; setBusy(true); setState('thinking'); setError(''); stopAudio();
   149	    const token = generation.current;
   150	    const abort = new AbortController(); controller.current = abort;
   151	    try {
   152	      const response = await fetch('/api/feedback', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ scenarioId, difficulty, customScenario, messages }), signal: abort.signal });
   153	      if (!response.ok) throw new Error(await responseError(response));
   154	      const feedback = await response.json();
   155	      if (token === generation.current) setReport(feedback);
   156	    } catch (cause) { if (token === generation.current && !abort.signal.aborted) setError(cause instanceof Error ? cause.message : 'Could not create feedback. Try again.'); }
   157	    finally { if (token === generation.current) { lock.current = false; setBusy(false); setState('idle'); } }
   158	  }
   159	
   160	  const avatarState = recorder.isRecording ? 'listening' : state;
   161	  const statusText = micStarting ? 'Connecting your microphone' : recorder.isRecording ? 'Listening to you' : state === 'thinking' ? 'Thinking it through' : state === 'speaking' ? `${counterpart.split(' · ')[0]} is speaking` : started ? 'Your turn. Take your time.' : 'Ready when you are';
   162	
   163	  return <main className="app-shell">
   164	    <header className="topbar"><a href="/" className="brand" aria-label="Rehearsal home"><span className="brand-mark"><MessageCircle size={20} /></span>rehearsal<span className="brand-dot">.</span></a><span className="topbar-note">A little practice. A little more confidence.</span><span className="preview-tag">Conversation studio</span></header>
   165	    <section className="page-heading"><div><div className="eyebrow">SPACE TO TRY, ROOM TO GROW</div><h1>{report ? 'Take the practice with you.' : started ? 'You’ve got the floor.' : 'Big conversation? Start here.'}</h1><p>{report ? 'A few useful things to bring into your real conversation.' : 'Rehearse the words before the moment. No pressure to get it perfect.'}</p></div><div className="session-chip"><span />{report ? 'Session complete' : started ? 'Practice in progress' : 'Your private practice space'}</div></section>
   166	    {(setupFailed || (setup && !setup.gemini)) && <div className="setup-notice" role="status"><strong>{setupFailed ? 'Could not check service availability.' : 'Connect Gemini to start practising.'}</strong> {setupFailed ? 'Refresh the page to try again.' : 'Add GEMINI_API_KEY to the server environment, then restart the app.'}</div>}
