    40	test('three turns preserve scenario/history, play voice, and produce feedback', async ({ page }) => {
    41	  await providers(page);
    42	  const requests: { scenarioId: string; difficulty: string; messages: { role: string; content: string }[] }[] = [];
    43	  await page.route('**/api/converse', route => {
    44	    requests.push(route.request().postDataJSON());
    45	    return route.fulfill({ json: { reply: `What evidence supports your request? Turn ${requests.length}.` } });
    46	  });
    47	  await page.goto('/');
    48	  await expect(page.getByRole('button', { name: 'Start practising' })).toBeEnabled();
    49	  await page.screenshot({ path: 'test-results/rehearsal-desktop.png', fullPage: true });
    50	  await page.getByRole('button', { name: /Ask for a raise/ }).click();
    51	  await page.getByLabel('Their approach').selectOption('challenging');
    52	  await page.getByRole('button', { name: 'Start practising' }).click();
    53	  const answers = ['I took ownership of onboarding.', 'It saved ten hours each month.', 'Could we agree on next steps?'];
    54	  for (const [index, answer] of answers.entries()) {
    55	    await page.getByLabel('Your answer').fill(answer);
    56	    await page.getByRole('button', { name: 'Send answer' }).click();
    57	    await expect(page.getByText(`What evidence supports your request? Turn ${index + 1}.`, { exact: true })).toBeVisible();
    58	    await expect(page.getByLabel('Your answer')).toBeEnabled();
    59	  }
    60	  expect(requests).toHaveLength(3);
    61	  expect(requests[2].scenarioId).toBe('raise');
    62	  expect(requests[2].difficulty).toBe('challenging');
    63	  expect(requests[2].messages.filter(m => m.role === 'user').map(m => m.content)).toEqual([
    64	    'I took ownership of onboarding.', 'It saved ten hours each month.', 'Could we agree on next steps?'
    65	  ]);
    66	  await page.getByRole('button', { name: 'End session & get feedback' }).click();
    67	  await expect(page.getByText(report.summary)).toBeVisible();
    68	  await expect(page.getByText(report.suggestedResponse, { exact: false })).toBeVisible();
    69	  await page.getByRole('button', { name: 'Practise another conversation' }).click();
    70	  await expect(page.getByRole('button', { name: 'Start practising' })).toBeVisible();
    71	  await expect(page.getByText('I took ownership of onboarding.', { exact: true })).toHaveCount(0);
    72	});
    73	
    74	test('microphone sends a genuine WAV, then transcribes and plays the reply', async ({ page }) => {
    75	  await providers(page);
    76	  let receivedAudio = false;
    77	  await page.route('**/api/transcribe', route => {
    78	    const body = route.request().postDataBuffer()!;
    79	    expect(route.request().headers()['content-type']).toBe('audio/wav');
    80	    expect(body.toString('ascii', 0, 4)).toBe('RIFF');
    81	    expect(body.toString('ascii', 8, 12)).toBe('WAVE');
    82	    expect(body.readUInt16LE(20)).toBe(1);
    83	    expect(body.readUInt16LE(34)).toBe(16);
    84	    receivedAudio = true;
    85	    return route.fulfill({ json: { text: 'I would like to discuss my responsibilities.' } });
    86	  });
    87	  await page.route('**/api/converse', route => route.fulfill({ json: { reply: 'What has changed in your role?' } }));
    88	  await page.goto('/');
    89	  await page.getByRole('button', { name: 'Start practising' }).click();
    90	  await page.getByRole('button', { name: 'Record your answer' }).click();
    91	  await expect(page.getByText('Listening to you', { exact: true })).toBeVisible();
    92	  // Give the synthetic test microphone enough samples to exercise the worklet.
    93	  await page.waitForTimeout(600);
    94	  await page.getByRole('button', { name: 'Finish & send' }).click();
    95	  await expect(page.getByText('I would like to discuss my responsibilities.', { exact: true })).toBeVisible();
    96	  await expect(page.getByText('What has changed in your role?', { exact: true })).toBeVisible();
    97	  await expect(page.getByRole('button', { name: 'Record your answer' })).toBeEnabled();
    98	  expect(receivedAudio).toBe(true);
    99	});
   100	
   101	test('failed speech preserves reply and allows a typed next turn', async ({ page }) => {
   102	  await providers(page);
   103	  await page.route('**/api/speak', route => route.fulfill({ status: 502, json: { error: 'Speech unavailable.' } }));
   104	  await page.route('**/api/converse', route => route.fulfill({ json: { reply: 'Tell me about the result.' } }));
   105	  await page.goto('/');
   106	  await page.getByRole('button', { name: 'Start practising' }).click();
   107	  await page.getByLabel('Your answer').fill('I built an onboarding tool.');
   108	  await page.getByRole('button', { name: 'Send answer' }).click();
   109	  await expect(page.getByText('Tell me about the result.', { exact: true })).toBeVisible();
   110	  await expect(page.getByRole('alert').filter({ hasText: 'Speech unavailable' })).toBeVisible();
   111	  await expect(page.getByLabel('Your answer')).toBeEnabled();
   112	});
   113	
   114	test('missing Gemini prevents a session instead of inventing answers', async ({ page }) => {
   115	  await page.route('**/api/status', route => route.fulfill({ json: { gemini: false, gradium: false } }));
   116	  await page.goto('/');
   117	  await expect(page.getByText('Connect Gemini to start practising.')).toBeVisible();
   118	  await expect(page.getByRole('button', { name: 'Start practising' })).toBeDisabled();
   119	});
