import type { Metadata } from 'next';
import './globals.css';

export const metadata: Metadata = {
  title: 'Rehearsal — Conversation Coach',
  description: 'A little practice for the conversations that matter. Rehearse with an AI counterpart and get practical feedback.',
};

export default function RootLayout({ children }: Readonly<{ children: React.ReactNode }>) {
  return <html lang="en"><body>{children}</body></html>;
}
import { Coach } from '@/components/coach';
export default function Page() { return <Coach />; }
export type AvatarState = 'idle' | 'listening' | 'thinking' | 'speaking';

export function Avatar({ state }: { state: AvatarState }) {
  return <div className={`avatar avatar-${state}`} aria-hidden="true">
    <svg viewBox="0 0 320 350" fill="none">
      <ellipse cx="160" cy="318" rx="104" ry="15" fill="#17243d" opacity=".09" />
